class Solution {
public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        auto f = [](const string& s) -> int {
            char min_c = 'z';
            for (char c : s) if (c < min_c) min_c = c;
            int cnt = 0;
            for (char c : s) if (c == min_c) cnt++;
            return cnt;
        };

        vector<int> word_freqs;
        word_freqs.reserve(words.size());
        for (const string& w : words) word_freqs.push_back(f(w));
        sort(word_freqs.begin(), word_freqs.end());

        int w_len = word_freqs.size();
        vector<int> res;
        res.reserve(queries.size());
        for (const string& q : queries) {
            int target = f(q);
            auto it = upper_bound(word_freqs.begin(), word_freqs.end(), target);
            res.push_back(w_len - distance(word_freqs.begin(), it));
        }
        return res;
    }
};

import java.util.*;

class Solution {
    int f(String s) {
        char minC = 'z';
        for (char c : s.toCharArray()) if (c < minC) minC = c;
        int cnt = 0;
        for (char c : s.toCharArray()) if (c == minC) cnt++;
        return cnt;
    }

    int upperBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] wordFreqs = new int[words.length];
        for (int i = 0; i < words.length; i++) wordFreqs[i] = f(words[i]);
        Arrays.sort(wordFreqs);

        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int target = f(queries[i]);
            int idx = upperBound(wordFreqs, target);
            res[i] = wordFreqs.length - idx;
        }
        return res;
    }
}

var numSmallerByFrequency = function(queries, words) {
    const f = (s) => {
        let minC = 'z';
        for (const c of s) if (c < minC) minC = c;
        let cnt = 0;
        for (const c of s) if (c === minC) cnt++;
        return cnt;
    };

    const wordFreqs = words.map(f).sort((a, b) => a - b);
    const upperBound = (arr, target) => {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    };

    return queries.map(q => {
        const target = f(q);
        const idx = upperBound(wordFreqs, target);
        return wordFreqs.length - idx;
    });
};
